Python:
from redwood import Session, Client

s = Session(retry_budget=30, budget_window_seconds=600, backoff_profile='standard')
client = Client(session=s)

# simple call uses session-budgeted retry
resp = client.generate(prompt='hello')

# streaming with resume hook
stream = client.start_stream(prompt='long chat')

@stream.on_resume
def handle_resume(token):
    print('resumed with token', token)

try:
    for chunk in stream:
        print(chunk.text)
except RetryBudgetExceeded:
    print('retry budget exhausted, please restart session')

TypeScript:
import { Session, Client, RetryBudgetExceeded } from '@redwood/sdk'

const s = new Session({ retryBudget: 20, budgetWindowSeconds: 300, backoffProfile: 'fast' })
const client = new Client({ session: s })

const stream = client.startStream({ prompt: 'interactive' })
stream.on('resume', (token) => console.log('resumed', token))

stream.on('data', (chunk) => console.log(chunk.text))
stream.on('error', (err) => {
  if (err instanceof RetryBudgetExceeded) {
    console.warn('budget exhausted')
  }
})
